/* ==== Desk Terminal, Mapped (r13-mut-2): the graphics mutant ================================
   Two rolled changes on Desk Terminal, nothing else.
   1. THE MAPPED PAGE. Every picture the tube draws is a plotted chart in one grammar: a dotted
      graticule, axes and rings labelled on the glass in VT323, and the family's things plotted as
      the page's own signals. WHERE (Ideas; the 404 and 403 empty): the family's map, home lit at
      the middle, north up, each place along its bearing as far out as the drive, on a time scale
      that opens the near half hour, labelled with its number from the list. WHEN (Home's Next up,
      Plans): the coming days plotted against the time of day, weekends shaded, Mondays ruled,
      the next plan lit and pinging, the rest as dots, each day's date under the axis. The idea
      rows carry the map too: a bearing needle turned the way each place lies.
   2. ONE FAMILY OF SIGNALS, one meaning each, on every page: the LAMP (lit #6dff9c, white-hot core,
      two-layer halo) is on: working, live, here; the DOT (solid steel) is waiting its turn; the
      RING (hollow pewter) is off or not set up; the BAR (amber; red once stopped) needs a look.
   ============================================================================================ */

/* ---- 2. Signals ------------------------------------------------------------------------------ */
.sig {
  display: inline-block; flex: none; box-sizing: border-box; width: 0.625rem; height: 0.625rem;
  margin: 0; padding: 0; border: 0; border-radius: 50%; background: none; box-shadow: none;
  animation: none; vertical-align: middle; forced-color-adjust: none;
}
.sig-lamp {
  background: radial-gradient(circle, #f4fff8 0 22%, #b9ffd1 38%, var(--green) 60%);
  box-shadow: 0 0 0 1px rgb(109 255 156 / 0.3), 0 0 4px rgb(109 255 156 / 0.85), 0 0 12px rgb(109 255 156 / 0.4);
}
.sig-dot { width: 0.4375rem; height: 0.4375rem; margin: 0.09375rem; background: #93b4c8; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.25); }
.sig-ring { background: none; box-shadow: inset 0 0 0 2px #8794a2; }
.sig-bar { width: 0.75rem; height: 0.3125rem; border-radius: 1.5px; background: var(--amber); box-shadow: 0 0 5px rgb(255 184 80 / 0.3); }
.sig-bar.red { background: var(--red); box-shadow: 0 0 5px rgb(255 107 107 / 0.35); }

/* Where the page's old lamps stood: each is now one of the four. */
.status-foot .sf-lamp.sig { width: 0.625rem; height: 0.625rem; border-radius: 50%; }
.status-foot .sf-lamp.sig-lamp { background: radial-gradient(circle, #f4fff8 0 22%, #b9ffd1 38%, var(--green) 60%); box-shadow: 0 0 0 1px rgb(109 255 156 / 0.3), 0 0 4px rgb(109 255 156 / 0.85), 0 0 12px rgb(109 255 156 / 0.4); animation: breathe 3.2s ease-in-out infinite; }
.status-foot .sf-lamp.sig-bar { width: 0.75rem; height: 0.3125rem; border-radius: 1.5px; background: var(--amber); box-shadow: 0 0 5px rgb(255 184 80 / 0.3); }
.status-foot .sf-lamp.sig-bar.red { background: var(--red); }
.now-mark .now-lamp.sig-lamp { width: 0.625rem; height: 0.625rem; animation: breathe 2.6s ease-in-out infinite; }
.dated .stop.sig-dot, .dated .is-today .stop.sig-dot { width: 0.4375rem; height: 0.4375rem; margin: 0.09375rem; border: 0; border-radius: 50%; background: #93b4c8; box-shadow: 0 0 0 3px var(--surface), inset 0 1px 0 rgb(255 255 255 / 0.25); }
.dated .is-today .stop.sig-dot { width: 0.5rem; height: 0.5rem; margin: 0.0625rem; background: var(--steel-cap); box-shadow: 0 0 0 3px var(--surface), 0 0 6px rgb(156 196 220 / 0.5); }
.her-state .lamp.sig-lamp { width: 0.625rem; height: 0.625rem; animation: breathe 3.2s ease-in-out infinite; }
.her-state.state-thinking .lamp.sig-lamp { animation-duration: 1.4s; }
.her-state .lamp.sig-bar, .her-state.state-lost .lamp.sig-bar { width: 0.75rem; height: 0.3125rem; border-radius: 1.5px; background: var(--amber); box-shadow: 0 0 5px rgb(255 184 80 / 0.3); animation: none; }
.key[aria-current]::after {
  width: 7px; height: 7px; margin-top: -3.5px;
  background: radial-gradient(circle, #f4fff8 0 22%, #b9ffd1 38%, var(--green) 62%);
  box-shadow: 0 0 0 1px rgb(109 255 156 / 0.3), 0 0 4px rgb(109 255 156 / 0.85), 0 0 10px rgb(109 255 156 / 0.4);
}
/* Chat: where the thread ends at the box, it is your turn: the lamp, not a lit ring. */
.track-end { left: calc(1.125rem - 0.375rem); top: 1.025rem; width: 0.75rem; height: 0.75rem; border: 0;
  background: radial-gradient(circle, #f4fff8 0 22%, #b9ffd1 38%, var(--green) 60%);
  box-shadow: 0 0 0 3px var(--surface), 0 0 0 4px rgb(109 255 156 / 0.3), 0 0 8px rgb(109 255 156 / 0.85), 0 0 18px rgb(109 255 156 / 0.4);
  animation: breathe 3.2s ease-in-out infinite; }
.to-status .light.sig-bar { position: absolute; top: 0.5rem; right: 0.35rem; font-size: 0; }

/* Status: one line to a signal, the signal centred in its column. */
.lights > .row > .sig, .lights > li > .sig { justify-self: center; align-self: center; }
.lights > li:not(.row) > .sig { align-self: start; margin-top: 0.5rem; }
.lights .row.long > .sig { align-self: start; margin-top: 0.75rem; }
/* The Contents plate on Status is an annunciator: each band's signals in a row after its name. */
.contents-list .c-sig { display: inline-flex; align-items: center; gap: 4px; flex: none; margin-left: 0.125rem; }
.contents-list .c-sig .sig-bar { width: 0.625rem; }
.sig-key { display: flex; flex-wrap: wrap; align-items: center; gap: 0.35rem 1rem; margin: 0.25rem 0 0.125rem; padding: 0.55rem 0 0.35rem 0.125rem;
  font: 400 var(--fs-note)/1.2 var(--mono); letter-spacing: 0.02em; color: color-mix(in srgb, var(--label) 90%, var(--plate)); border-top: 1px solid #1d2428; }
.sig-key > span { display: inline-flex; align-items: center; gap: 0.4rem; white-space: nowrap; }
.waiting-list > li { display: flex; align-items: center; gap: 0.6rem; }
/* Late, on Home and To do: the bar before the words that say so. */
.warn > .sig-bar, .due.warn > .sig-bar { margin: 0 0.45rem 0 0; vertical-align: 0.2em; }
.contents-list .c-late::before { content: none; }
.contents-list .c-late > .sig-bar { margin: 0 0.45rem 0 0.1rem; }

/* ---- 1. The mapped page: one chart grammar on the glass --------------------------------------- */
.plot.when-plot, .plot.where-plot { position: relative; overflow: visible; margin: 0.5rem 0 0; }
.chart { display: block; width: 100%; height: auto; overflow: visible; filter: drop-shadow(0 0 2px color-mix(in srgb, var(--phosphor) 50%, transparent)); }
.chart * { vector-effect: non-scaling-stroke; }
.chart .grat { fill: none; stroke: color-mix(in srgb, var(--phosphor) 17%, transparent); stroke-width: 1; stroke-dasharray: 1 3; }
.chart .week { fill: none; stroke: color-mix(in srgb, var(--phosphor) 30%, transparent); stroke-width: 1; stroke-dasharray: 3 3; }
.chart .wkend rect { fill: color-mix(in srgb, var(--phosphor) 8%, transparent); }
.chart .axis { fill: none; stroke: color-mix(in srgb, var(--phosphor) 55%, transparent); stroke-width: 1.25; }
.chart .axis-cross { fill: none; stroke: color-mix(in srgb, var(--phosphor) 11%, transparent); stroke-width: 1; }
.chart .now-line { fill: none; stroke: var(--phosphor); stroke-width: 1.5; }
.chart .now-flag, .chart .needle { fill: var(--phosphor); }
.chart .tick { font: 400 17px/1 var(--terminal); fill: color-mix(in srgb, var(--phosphor) 58%, transparent); }
.chart .tick.wk { fill: color-mix(in srgb, var(--phosphor) 80%, transparent); }
.chart .ring { fill: none; stroke: color-mix(in srgb, var(--phosphor) 32%, transparent); stroke-width: 1; stroke-dasharray: 4 3; }
.chart .ring.outer { stroke: color-mix(in srgb, var(--phosphor) 42%, transparent); stroke-dasharray: none; }
.chart .ring-label { font: 400 16px/1 var(--terminal); fill: color-mix(in srgb, var(--phosphor) 52%, transparent); }
.chart .home-word { font-size: 16px; fill: color-mix(in srgb, var(--phosphor) 70%, transparent); }
/* The marks are the page's signals, drawn in phosphor: a dot waits, the lamp is here or next. */
.chart .mark .halo { fill: color-mix(in srgb, var(--phosphor) 22%, transparent); }
.chart .mark .core { fill: #a9ffc7; }
.chart .mark.lamp .halo { fill: color-mix(in srgb, var(--phosphor) 42%, transparent); animation: breathe 2.6s ease-in-out infinite; }
.chart .mark.lamp .core { fill: #f0fff5; }
.chart .mark.first .core { fill: #d8ffe6; }
.chart .ping { fill: none; stroke: rgb(146 255 184 / 0.9); stroke-width: 1; transform-box: fill-box; transform-origin: center; animation: ping 3.2s cubic-bezier(0.15, 0.7, 0.35, 1) infinite; }
.chart .drop { fill: none; stroke: color-mix(in srgb, var(--phosphor) 34%, transparent); stroke-width: 1; stroke-dasharray: 1 2; }
.chart .day { font: 400 19px/1 var(--terminal); fill: color-mix(in srgb, var(--phosphor) 66%, transparent); }
.chart .day.on { fill: #d8ffe6; }
.chart .label { font: 400 21px/1 var(--terminal); fill: #c8ffdb; paint-order: stroke; stroke: #06100a; stroke-width: 3px; stroke-linejoin: round; }
.chart .leader { fill: none; stroke: color-mix(in srgb, var(--phosphor) 50%, transparent); stroke-width: 1; }
.chart .nofix { fill: none; stroke: var(--phosphor); stroke-width: 2; }
.chart .say { font: 400 60px/1 var(--terminal); fill: var(--phosphor); animation: flicker 6s linear infinite; }

/* Home: Next up's words across the glass, the chart of what is coming under them. */
.next-block.charted { grid-template-columns: minmax(0, 1fr); gap: 0; }
.next-block.charted .when-plot { grid-column: 1; grid-row: 2; margin: 0.45rem 0 0; }
/* Plans: the same chart, taller, under Next up. */
.plan-trace .when-plot { margin-top: 0.55rem; }
/* Ideas: the map square at the left of the glass, as the radar was, twice its size; the words
   beside it; the nearest and the furthest under both. */
.mapped .crt-tube { padding: 0.75rem 0.875rem 0.875rem; }
.map-row { display: grid; grid-template-columns: minmax(0, 1fr) 7.5rem; gap: 0.5rem; align-items: center; }
.map-row .where-plot { margin: 0; }
.map-words p { margin: 0; }
.map-words .on-radar-label { font-size: 1.25rem; margin-bottom: 0.35rem !important; white-space: nowrap; }
.map-words .on-radar-label .caps { letter-spacing: 0.03em; }
.map-words .on-radar-count { font-size: 1.625rem; line-height: 1; }
.map-words .on-radar-listed { margin-top: 0.4rem !important; font-size: 1.125rem; white-space: nowrap; }
.mapped .on-radar-line { margin-top: 0.4rem !important; }
/* 404 and 403: the empty map beside the readout. */
.lost-scope .where-plot { margin: 0; }
.lost-scope .chart .ring-label { display: none; }

/* The rows carry the map: a needle turned the way each place lies from home. The Drive column
   is 1.5rem wider than Desk Terminal's to make room for it. */
@media (min-width: 52rem) {
  .idea-list > .row { grid-template-columns: 1.5rem minmax(0, max-content) auto minmax(0.75rem, 1fr) 9rem 7.75rem 2.5rem; }
  .idea-band .colheads .ch-drive { width: 9rem; padding-right: 3rem; }
}
.icon.bearing { width: 0.75rem; height: 0.75rem; margin: 0 0.3rem 0 0.4rem; vertical-align: -0.04em; color: color-mix(in srgb, var(--label) 85%, transparent); }
.bearing.to-ne { transform: rotate(45deg); } .bearing.to-e { transform: rotate(90deg); } .bearing.to-se { transform: rotate(135deg); }
.bearing.to-s { transform: rotate(180deg); } .bearing.to-sw { transform: rotate(225deg); } .bearing.to-w { transform: rotate(270deg); }
.bearing.to-nw { transform: rotate(315deg); }
.idea-card:hover .icon.bearing { color: var(--denim); }
@media (max-width: 40rem) {
  .idea-list .way { display: none; }
  .icon.bearing { margin-right: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .chart .ping, .chart .mark.lamp .halo, .chart .say, .status-foot .sf-lamp.sig-lamp, .now-mark .now-lamp.sig-lamp, .her-state .lamp.sig-lamp, .track-end { animation: none; }
  .chart .ping { opacity: 0.4; transform: scale(2.2); }
}
@media (prefers-contrast: more) {
  .chart { filter: none; }
  .sig-ring { box-shadow: inset 0 0 0 2px #c3ccd6; }
}
@media (forced-colors: active) {
  .sig { border: 1px solid CanvasText; }
  .sig-lamp, .sig-dot, .sig-bar { background: CanvasText; box-shadow: none; }
  .sig-ring { background: Canvas; }
}

/* ==== r14-mut-3: three rolled changes on Desk Terminal, Mapped (everything above is the parent's) ====
   LIST   .rows: every other row on a faint ground band, so the eye keeps its line across the facts column.
   HEAD   .page-head: the page's one primary action (.head-add) at the head's right end, the title a step up (40 to 48).
   COLOUR :root tokens: the ground one step cooler (hue 156 to 172), the neutral words one step warmer (hue 86 to 79).
   ====================================================================================================== */

/* ---- COLOUR: the ground a step cooler, the neutral words a step warmer ----------------------------
   The sheet writes its own :root, so the change is stated here, after it (the palette tokens say the same). */
:root {
  --bg: #0a0e0d;                                   /* hue 156 to 172: a breath cooler, still green-black */
  --ink: #d8d0c2; --ink-2: #bab1a4; --dim: #a49c90; --faint: #978f83;   /* hue 86 to 79: a breath warmer */
  --heading: #efe6d8;
}

/* ---- LIST: the band --------------------------------------------------------------------------- */
.rows { --band: color-mix(in srgb, var(--steel-cap) 5%, transparent); }
:where(.rows) > .row:nth-child(even),
:where(.rows > .row-wrap:nth-child(even)) > .row { background-color: var(--band); }
/* A state still wins over the band: pointed at, today and late keep their own grounds. */
@media (forced-colors: active) { :where(.rows) > .row:nth-child(even) { background-color: transparent; } }

/* ---- HEAD: title one step up, the action at the right end ------------------------------------------ */
.page-head { align-items: flex-end; }
.page-head h1 { font-size: 3rem; line-height: 1.02; letter-spacing: -0.02em; }
.page-head .title-icon .icon { width: 2rem; height: 2rem; }
.page-head .title-icon.presence { width: 3rem; height: 3rem; }
.page-head .page-actions { flex: none; margin-left: auto; align-self: flex-start; padding-top: 0.25rem; }
.page-head .head-add { flex: none; white-space: nowrap; }
@media (max-width: 40rem) {
  .page-head h1 { font-size: 2.75rem; }
}


/* ==== r17-head-1 (base r16-head-1): Desk Terminal, Banded + r15-mut-2's COLOUR and FOOT + r15-mut-1's CONTROLS ====
   COLOUR  steel-slate case, thin section-coloured band lines (lifted from r15-mut-2)
   FOOT    current page in the bar marked by a short rule (r15-mut-2)
   CONTROLS select as a raised key with a flipping chevron, clean picker list, bright Send key (r15-mut-1)
   ====================================================================================================== */

/* ---- COLOUR: glass, case and thin lines -------------------------------------------------------------
   The ground goes a breath greener (glass), the slate a breath towards steel-teal (case), every
   structural line follows it. The phosphor stays the machine's own light; the companions are lines,
   never fills. The sheet writes its own :root and hard-codes a few greys, so they are restated here. */
:root {
  --bg: #091110;
  --surface: #111a1c; --surface-2: #172224; --surface-3: #1d2a2d; --field: #091214;
  --line: #1e2c2e; --line-2: #2b4043; --edge: #62797d;
  --rule: #2a3c3f; --body: #162022; --body-2: #121b1d; --plate: #0c1517;
  --key: #1c2629; --key-hi: #233035; --key-edge: #3a4a4e;
}
.bar { background: rgb(14 22 24 / 0.94); border-bottom-color: #1d2c2f; }
.tools { border-left-color: #223336; }
@media (max-width: 51.99rem) { .places { background: rgb(14 22 24 / 0.97); border-top-color: #223336; } }
.panel, .card, .said-bot .bubble, .tabs { border-color: #27393c; }

/* The lines: a band's top edge and the short cap under its head take the colour of what it holds. */
.band { --c: var(--accent); }
.band.coming { --c: var(--plans); }
.band.home-todo, .band.todo-band { --c: var(--todo); }
.band.lately, .band.idea-band, .band.capture { --c: var(--ideas); }
.band.home-wishes { --c: var(--shows); }
.band.setup, .band.trouble, .band.attention { --c: var(--people); }
.band { border-top: 2px solid color-mix(in srgb, var(--c) 50%, var(--rule)); }
.band.setup, .band.trouble { border-top-color: var(--amber-edge); }
.band.attention { border-top-color: color-mix(in srgb, var(--red) 55%, var(--rule)); }
.band-head {
  padding-bottom: 0.4rem; margin-bottom: 0.5rem;
  background:
    linear-gradient(var(--c), var(--c)) left bottom / 2.5rem 2px no-repeat,
    linear-gradient(color-mix(in srgb, var(--c) 22%, var(--line)), color-mix(in srgb, var(--c) 22%, var(--line))) left bottom / 100% 1px no-repeat;
}
.band-head .ring:not(.look) { border-color: color-mix(in srgb, var(--c) 55%, var(--steel-line)); }

/* ---- FOOT: the bar marks the page you are on with a short rule under it ------------------------------ */
.bar { --foot-rule: var(--accent); }
.bar .places a[aria-current="page"], .bar .tools > a[aria-current="page"], .bar .menu.here > summary,
.bar .places a[aria-current="page"]:hover, .bar .menu.here > summary:hover {
  color: var(--heading); box-shadow: none;
  background: linear-gradient(var(--foot-rule), var(--foot-rule)) 50% calc(100% - 0.2rem) / 2.25rem 3px no-repeat;
}
.bar .places a[aria-current="page"] .icon, .bar .tools > a[aria-current="page"] .icon, .bar .menu.here > summary .icon {
  color: var(--accent); background: none; box-shadow: none; filter: none;
}
.menu.here > summary::after { border-color: var(--ink-2); }
@media (max-width: 51.99rem) {
  .bar .places a[aria-current="page"] {
    background: linear-gradient(var(--foot-rule), var(--foot-rule)) 50% calc(100% - 0.1rem) / 2.25rem 4px no-repeat;
  }
  .bar .places a[aria-current="page"] .icon { background: none; box-shadow: none; color: var(--accent); }
}

/* ---- CONTROLS: the select a raised key, a chevron that flips, a clean list; Send brighter -------------- */
@supports (appearance: base-select) {
  select, .ask .who select {
    justify-content: space-between; gap: 0.7rem; padding-inline: 0.85rem 0.8rem;
    color: var(--heading); font-weight: 500; cursor: pointer;
    background: linear-gradient(180deg, var(--key-hi), var(--key)); background-image: linear-gradient(180deg, var(--key-hi), var(--key));
    border: 1px solid var(--key-edge); border-bottom-color: var(--line-2); border-top-color: color-mix(in srgb, var(--steel-cap) 45%, var(--key-edge)); border-radius: 3px;
    box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.07), 0 2px 0 #060b0c, 0 10px 18px -14px #000;
  }
  select:hover, .ask .who select:hover { color: #fff; background: linear-gradient(180deg, color-mix(in srgb, white 4%, var(--key-hi)), var(--key-hi)); border-color: var(--steel); border-top-color: var(--steel-cap); }
  select:focus, .ask .who select:focus, select:open, .ask .who select:open {
    border-color: var(--green); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.07), 0 2px 0 #060b0c, var(--bloom);
  }
  select:active, .ask .who select:active { transform: translateY(1px); box-shadow: inset 0 2px 4px rgb(0 0 0 / 0.5); }
  select::picker-icon {
    display: block; content: ""; flex: none; width: 0.42rem; height: 0.42rem; margin: -0.22rem 0.1rem 0 0;
    border: solid var(--steel-cap); border-width: 0 2px 2px 0; rotate: 45deg; transition: rotate 0.15s, margin 0.15s;
  }
  select:open::picker-icon { rotate: 225deg; margin-top: 0.18rem; border-color: var(--lit); }
  ::picker(select) {
    margin-top: 0.3rem; padding: 0.3rem; background: var(--surface-2); border: 1px solid var(--key-edge); border-radius: 3px;
    box-shadow: 0 18px 36px -14px #000, inset 0 1px 0 rgb(255 255 255 / 0.04);
  }
  select option { min-height: 2.5rem; padding: 0.45rem 0.7rem; border-radius: 2px; color: var(--ink-2); font-weight: 400; }
  select option:hover, select option:focus-visible { color: var(--heading); background: var(--surface-3); }
  select option:checked { color: var(--heading); font-weight: 600; background: none; }
  select option::checkmark { color: var(--lit); }
}
/* Send: the bright green key, raised: a lit lip along its top and a ring of its own light. */
.ask .send {
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.35), inset 0 -2px 0 rgb(0 80 30 / 0.28), 0 0 0 1px rgb(109 255 156 / 0.55), 0 0 14px -2px rgb(109 255 156 / 0.8), 0 8px 26px -10px rgb(109 255 156 / 0.75);
}
.ask .send:hover {
  background: var(--green-hover);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.45), inset 0 -2px 0 rgb(0 80 30 / 0.22), 0 0 0 1px rgb(146 255 184 / 0.7), 0 0 20px -2px rgb(109 255 156 / 0.95), 0 10px 34px -10px rgb(109 255 156 / 0.9);
}
.ask .send:active { transform: translateY(1px); box-shadow: inset 0 2px 4px rgb(0 60 20 / 0.4), 0 0 10px -2px rgb(109 255 156 / 0.7); }


/* ==== r17-head-1: Desk Terminal, Banded + Dialled's FIGURE + Folded Slate's COLOUR ===================
   FIGURE  (from r16-mut-2) the Status tube's spend dial: .spend-meter, .readout-line, .dial*, .needle*; _ui.html spend_meter
   COLOUR  (from r16-mut-1) teal-black ground, warm cream ink, slate plates, thin section-coloured lines (its glass fold and numerals are not lifted)
   ====================================================================================================== */

/* ---- COLOUR ------------------------------------------------------------------------------------------
   Ground: a deeper teal-black. Words: a cream with more yellow in it (hue 80 to 83, a step brighter).
   Plates: the desk's slate turns from teal to blue-grey, so the cards read as metal against a green
   ground. Lines: slate rails; each band's own lines take the colour of what it holds. Companions: sage
   (the lit, done and outing colour) and steel-cyan (here, links, the case's cap). The phosphor stays the
   machine's own light. The sheet hard-codes some of these, so they are restated here. */
:root {
  --bg: #071211;
  --surface: #141c21; --surface-2: #1a242b; --surface-3: #212e36; --field: #0a1317;
  --line: #1d2a30; --line-2: #2c3b44; --edge: #6a7b85; --rule: #2c3b44;
  --ink: #ddd1bc; --ink-2: #bdb19e; --dim: #a89c89; --faint: #998d7b; --heading: #f1e6d1;
  --label: #a2b4c2; --secondary: #b3c4d1;
  --body: #161f24; --body-2: #12191d; --plate: #0c1418;
  --key: #1c262c; --key-hi: #243139; --key-edge: #3b4b55;
  --steel: #6f8ba0; --steel-cap: #a4c8dc; --steel-line: #4d6578; --denim: #a2c5dc;
  --lit: #86d9a6; --outing: #86d9a6; --sage: #86d9a6;
  --rail: #36495a; --rail-hi: #587187;
}
html { scrollbar-color: #36444e var(--bg); }
.bar { background: rgb(13 22 26 / 0.94); border-bottom-color: #22323b; }
.tools { border-left-color: #263841; }
@media (max-width: 51.99rem) { .places { background: rgb(13 22 26 / 0.97); border-top-color: #263841; } }
.panel, .card, .said-bot .bubble, .tabs { border-color: #2d3e48; }
/* Thin section-coloured lines: each band's rows, its column heads and its head's rule take its colour. */
.band .rows .row { border-bottom-color: color-mix(in srgb, var(--c) 17%, var(--line)); }
.band .colheads { border-bottom-color: color-mix(in srgb, var(--c) 34%, var(--line-2)); }
.band .rows .lead { border-bottom-color: color-mix(in srgb, var(--c) 38%, #3a4650); }
.band-head h2 .icon { color: color-mix(in srgb, var(--c) 82%, var(--ink)); }
.page-head { padding-bottom: 0.6rem; border-bottom: 1px solid color-mix(in srgb, var(--accent) 26%, var(--line)); }
/* Sage: what is done, lit or on its way. Steel-cyan: where you are and where a link goes. */
.contents-list a:hover .ring:not(.look), .contents-list .ring:not(.look) { border-color: color-mix(in srgb, var(--sage) 55%, var(--rail)); }
.sf-spend, .sf-who { color: color-mix(in srgb, var(--sage) 28%, var(--dim)); }
.plate-name, .keys-name { color: color-mix(in srgb, var(--steel-cap) 62%, var(--label)); }
.terminal { border-color: #2f4049; }

/* ---- FIGURE: the spend dial ----------------------------------------------------------------------- */
.spend-meter { --hot: #e4fff0; }
.readout.near { --phosphor: var(--amber); }
.readout.over { --phosphor: var(--red); --phosphor-dim: color-mix(in srgb, var(--phosphor) 80%, #07120c); }
.spend-meter .crt-tube { padding: 0.6rem 0.9rem 0.5rem; }
.readout-line { display: flex; align-items: flex-end; gap: 0.5rem; margin: 0 0 0.1rem; }
.readout .readout-figure { margin: 0; font-size: 2.75rem; line-height: 0.85; }
.readout .readout-label { display: block; margin: 0 0 0.1rem; font-size: 1.25rem; line-height: 1; color: var(--phosphor-dim); }
.readout-side { display: grid; justify-items: end; gap: 0.15rem; margin: 0 0 0 auto !important; font-size: 1.1rem; line-height: 1; }
.readout-pct { color: var(--phosphor-bright); }
.readout-avg { display: flex; align-items: center; gap: 0.4rem; }
.ghost-key { width: 1rem; height: 2px; background: var(--phosphor); opacity: 0.45; }
.dial { display: block; width: 100%; height: auto; margin: 0.2rem 0 0; overflow: hidden; }
.dial-band { fill: none; stroke: var(--phosphor); stroke-width: 11; opacity: 0.24; }
.dial-fill-halo { fill: none; stroke: var(--phosphor); stroke-width: 22; opacity: 0.2; }
.dial-fill { fill: none; stroke: var(--phosphor); stroke-width: 11; }
.dial-caution { fill: none; stroke: var(--phosphor-bright); stroke-width: 11; stroke-dasharray: 1.4 4.6; opacity: 0.5; }
.dial-over { fill: none; stroke: var(--phosphor-bright); stroke-width: 11; stroke-dasharray: 2.2 2.4; opacity: 0.7; }
.dial-arc { fill: none; stroke: var(--phosphor); stroke-width: 1.5; opacity: 0.7; }
.dial-ticks { fill: none; stroke: var(--phosphor); stroke-width: 1.25; opacity: 0.75; }
.dial-ticks.major { stroke-width: 2.25; opacity: 0.95; }
.dial-limit-halo { fill: none; stroke: var(--phosphor); stroke-width: 11; stroke-linecap: round; opacity: 0.28; }
.dial-limit { fill: none; stroke: var(--phosphor-bright); stroke-width: 4; stroke-linecap: round; }
.dial-tag { fill: var(--phosphor-bright); }
.dial-tag-text { font: 400 20px/1 var(--terminal); letter-spacing: 0.04em; fill: #05110a; }
.dial-num { font: 400 20px/1 var(--terminal); fill: var(--phosphor-dim); }
.dial-unit { font: 400 18px/1 var(--terminal); letter-spacing: 0.14em; fill: var(--phosphor-dim); }
.dial-hub { fill: #07130d; stroke: var(--phosphor); stroke-width: 2; }
.dial-hub-cap { fill: var(--phosphor-bright); }
.needle-core { fill: none; stroke: var(--hot); stroke-width: 2.25; }
.needle-halo { fill: none; stroke: var(--phosphor); stroke-width: 9; opacity: 0.3; }
.needle-tip { fill: none; stroke: #fff; stroke-width: 3.5; }
.needle-ghost { fill: none; stroke: var(--phosphor); stroke-width: 2; stroke-dasharray: 4 4; opacity: 0.45; }
.dial .needle { transform-box: view-box; transform-origin: 200px 262px; animation: swing 1.3s cubic-bezier(0.3, 0.7, 0.4, 1) 0.45s both; }
@keyframes swing { 0% { rotate: 0deg; } 26% { rotate: 17deg; } 50% { rotate: 2deg; } 70% { rotate: 6deg; } 86% { rotate: 0.5deg; } 100% { rotate: 0deg; } }
@media (max-width: 40rem) { .readout .readout-figure { font-size: 2.25rem; } }
@media (prefers-reduced-motion: reduce) { .dial .needle { animation: none; } }
@media (prefers-contrast: more) { .needle-halo, .needle-ghost { opacity: 0.6; } }

/* ---- SIGNAL: the glass's status line (r17-mut-1, lifted from r16-head-2): .glass-status in home.html's tube block ---- */
.glass-status { display: flex; align-items: center; flex-wrap: wrap; gap: 0.2rem 0.6rem; margin: 0 0 0.45rem; padding: 0; font: 400 1.1rem/1.2 var(--terminal); letter-spacing: 0.02em; color: color-mix(in srgb, var(--phosphor) 72%, var(--ink-2)); text-shadow: 0 0 6px color-mix(in srgb, var(--phosphor) 38%, transparent); }
.glass-status::before { content: ""; flex: none; width: 10px; height: 10px; border-radius: 50%; background: radial-gradient(circle at 50% 45%, #f4fff8 0 30%, var(--phosphor) 66%); box-shadow: 0 0 4px var(--phosphor), 0 0 10px color-mix(in srgb, var(--phosphor) 65%, transparent), 0 0 18px 1px color-mix(in srgb, var(--phosphor) 48%, transparent); }
.glass-status a { color: inherit; text-decoration: underline; text-underline-offset: 0.2em; }
.glass-status[data-state=thinking]::before { animation: lamp-swell 3.2s ease-in-out infinite; }
.glass-status:is([data-state=retrying], [data-state=lost]) { color: var(--people); text-shadow: none; }
.glass-status:is([data-state=retrying], [data-state=lost])::before { background: var(--people); box-shadow: 0 0 6px color-mix(in srgb, var(--people) 60%, transparent); }
@keyframes lamp-swell { 50% { box-shadow: 0 0 4px var(--phosphor), 0 0 12px var(--phosphor), 0 0 24px 3px color-mix(in srgb, var(--phosphor) 56%, transparent); } }
@media (prefers-reduced-motion: reduce) { .glass-status[data-state=thinking]::before { animation: none; } }

/* ---- LIST (r17-mut-1): every list row one step tighter, its facts right-aligned on tabular figures ----
   A row is still a 44px box (the target does not shrink); the boxes overlap by 8px so the pitch is 36px, its rule
   and its afterglow are drawn on the 36px cell, and its facts end on one right edge under a right-aligned head. */
.rows .row:not(.empty) { min-height: 2.75rem; border-bottom-width: 0; isolation: isolate; }
.rows > .row:not(.empty) + .row:not(.empty), .rows > .row-wrap + .row-wrap { margin-top: -0.5rem; }
.rows .row:not(.empty)::after { content: ""; position: absolute; inset: auto 0 0.25rem; border-bottom: 1px solid; border-bottom-color: inherit; pointer-events: none; }
.rows > :last-child:not(.empty)::after, .rows > :last-child > .row::after { content: none; }
.rows .row:not(.empty):not(.step)::before { content: ""; position: absolute; inset: 0.25rem 0; z-index: -1; pointer-events: none; transition: background-color var(--afterglow), box-shadow var(--afterglow); }
.rows .row:not(.empty):not(.step):hover, .rows a.row:not(.step):focus-visible { background: none; box-shadow: none; }
.rows .row:not(.empty):not(.step):hover::before, .rows a.row:not(.step):focus-visible::before { background: color-mix(in srgb, var(--steel) 12%, transparent); box-shadow: inset 2px 0 0 #86d9a6; transition-duration: var(--glow-in); }
.rows :is(.f, .who, .for, .drive, .time, .rel) { font-variant-numeric: tabular-nums slashed-zero; text-align: right; }
.dated .f { grid-template-columns: 3.5rem 7rem; }
.dated .f > * { text-align: right; }
.checklist .who, .timetable .who, .lately .for, .idea-list .for { justify-self: end; padding-right: 0.75rem; }
.home-todo .colheads .ch-who, .todo-band .colheads .ch-who, .lately .colheads .ch-for, .idea-band .colheads .ch-for { text-align: right; padding: 0 0.75rem 0 0; }

/* ==== r18-mut-1: three rolled changes on Desk Terminal, Gauged Rows ============================
   GLASS  one Vera card (greeting, question on a strip of glass, status line, box, ways to start) beside a bezelled tube on a
          grid floor, across the top of Home. Classes: .vera-row .vera-card .vera-top .vera-glass .vera-deck .vera-tube .tube-floor
   SIGNAL the status line under the question made more of: .glass-status .gs-lamp .gs-words .gs-pips
   TYPE   reading prose at 1.55 leading, never wider than 66 characters
   ============================================================================================== */

/* ---- GLASS: the row, and Home's grid with a row above the terminal and the desk ---------------- */
.vera-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1rem; min-width: 0; }
@media (min-width: 64rem) {
  .vera-row { grid-template-columns: minmax(0, 1.22fr) minmax(0, 1fr); gap: 1.5rem; align-items: stretch; }
  .page-home main > .vera-row { grid-column: 1 / -1; grid-row: 1; }
  .page-home main > .terminal, .page-home main > .desk { grid-row: 2; }
}

/* The card: the machine's graphite body, as the terminal was, with the corner that is lit. */
.vera-card {
  position: relative; isolation: isolate; display: flex; flex-direction: column; gap: 0.75rem; min-width: 0;
  padding: 0.875rem 1rem 1rem; color: var(--ink);
  background:
    radial-gradient(70% 40% at 100% 0%, rgb(79 96 230 / 0.12), transparent 72%),
    linear-gradient(180deg, #1a1f22, var(--body) 34%, var(--body-2));
  border: 1px solid #2a3034; border-radius: 14px;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.07), inset 0 0 0 1px rgb(0 0 0 / 0.3), 0 30px 50px -36px rgb(0 0 0 / 0.95), 0 0 46px -30px color-mix(in srgb, var(--brand) 50%, transparent);
}
.vera-card::before {
  content: ""; position: absolute; top: -1px; left: -1px; width: 1.1rem; height: 1.1rem; pointer-events: none;
  border-top: 2px solid var(--brand); border-left: 2px solid var(--brand); border-top-left-radius: 14px;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--brand) 75%, transparent));
}
.vera-top { display: flex; align-items: center; gap: 0.6rem; margin: 0; padding: 0 0 0.6rem; border-bottom: 1px solid #2a3034; }
.vera-top .presence { width: 1.75rem; height: 1.75rem; border-radius: 5px; }
.vera-top .presence .presence-glass { font-size: 4.7px; }
.vera-top .vera-who { font: 600 var(--fs-head)/1 var(--cond); letter-spacing: -0.005em; color: var(--heading); }
.vera-top .vera-date { margin: 0 0 0 auto; }

/* The strip of glass the question is typed on: the tube's own recess, in the card. */
.vera-glass {
  --phosphor: var(--screen);
  --phosphor-bright: color-mix(in srgb, var(--phosphor) 45%, #fff);
  --phosphor-dim: color-mix(in srgb, var(--phosphor) 64%, #07120c);
  --phosphor-glass: color-mix(in srgb, var(--phosphor) 9%, #060a08);
  position: relative; isolation: isolate; overflow: hidden; display: grid; gap: 0.3rem;
  padding: 0.95rem 1.1rem 0; color: var(--phosphor); font: 400 var(--tube)/1.1 var(--terminal);
  background: radial-gradient(125% 115% at 30% 40%, var(--phosphor-glass), #07100b 55%, #030705);
  border-radius: 8px / 10px;
  box-shadow: inset 0 0 0 1.5px #020403, 0 0 0 1px #1c2023, 0 1px 0 1px rgb(255 255 255 / 0.05), inset 0 0 36px 6px rgb(0 0 0 / 0.72);
  text-shadow: 0 0 1px color-mix(in srgb, var(--phosphor) 80%, transparent), 0 0 9px color-mix(in srgb, var(--phosphor) 45%, transparent), 0 0 24px color-mix(in srgb, var(--phosphor) 20%, transparent);
}
.vera-glass > * { position: relative; z-index: 1; margin: 0; }
.vera-glass > :not(.glass-status) { filter: blur(0.35px); }
.vera-glass::before { content: ""; position: absolute; inset: 0; z-index: 3; pointer-events: none; background: repeating-linear-gradient(to bottom, rgb(2 5 3 / 0.4) 0 1px, transparent 1px 3px); }
.vera-glass::after { content: ""; position: absolute; inset: 0; z-index: 4; pointer-events: none; border-radius: inherit; background: radial-gradient(85% 50% at 26% 4%, rgb(255 255 255 / 0.07), transparent 62%), radial-gradient(135% 125% at 50% 42%, transparent 55%, rgb(0 0 0 / 0.6)); }
.vera-glass .ask-question { margin: 0.1rem 0 0; font-size: 2.75rem; line-height: 1; }
.vera-glass .apos { font: 400 0.8em/1 var(--mono); margin: 0 0.04em 0 0.02em; }
.vera-glass .tube-said { font-size: 1.25rem; line-height: 1.1; }
.vera-glass .dim { color: var(--phosphor-dim); }
.vera-glass a { color: inherit; text-decoration: underline; text-decoration-color: color-mix(in srgb, currentColor 55%, transparent); text-decoration-thickness: 2px; text-underline-offset: 0.16em; }
.vera-glass a:hover { color: #04100a; background: var(--phosphor); text-decoration: none; text-shadow: none; }
.vera-glass a:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }
.vera-plain { margin: 0; font: 600 var(--fs-page)/1.05 var(--cond); color: var(--heading); }

/* The box under the glass: the card's keyboard. */
.vera-deck { display: flex; flex-direction: column; gap: 0.625rem; min-width: 0; }
.vera-deck .ask textarea { min-height: 4rem; }

/* ---- SIGNAL: the status line, made more of -----------------------------------------------------
   A strip across the foot of the glass: a lamp with a ring that breathes out, "Listening" lit and
   what she is watching dim after it, and one lit tick at the right for each plan she is watching. */
.vera-glass .glass-status {
  display: flex; flex-wrap: nowrap; align-items: center; gap: 0.75rem; margin: 0.6rem -1.1rem 0; padding: 0.55rem 1.1rem;
  font: 400 1.35rem/1.1 var(--terminal); letter-spacing: 0.03em; color: var(--phosphor-dim);
  background: linear-gradient(90deg, color-mix(in srgb, var(--phosphor) 15%, transparent), color-mix(in srgb, var(--phosphor) 3%, transparent) 75%);
  border-top: 1px solid color-mix(in srgb, var(--phosphor) 34%, transparent);
  text-shadow: 0 0 6px color-mix(in srgb, var(--phosphor) 32%, transparent);
}
.vera-glass .glass-status::before { content: none; }
.gs-lamp { position: relative; flex: none; width: 0.875rem; height: 0.875rem; border-radius: 50%; background: radial-gradient(circle at 50% 45%, #f4fff8 0 30%, var(--brand) 68%); box-shadow: 0 0 4px var(--brand), 0 0 11px var(--brand), 0 0 22px 2px color-mix(in srgb, var(--brand) 50%, transparent); animation: gs-breathe 3.6s ease-in-out infinite; }
.gs-lamp::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; border: 1px solid color-mix(in srgb, var(--brand) 70%, transparent); opacity: 0; animation: gs-ring 3.6s ease-out infinite; }
.gs-words { min-width: 0; }
.gs-words b { font-weight: 400; text-transform: uppercase; letter-spacing: 0.1em; color: var(--phosphor-bright); text-shadow: 0 0 1px #a9ffc7, 0 0 8px color-mix(in srgb, var(--phosphor) 70%, transparent), 0 0 18px color-mix(in srgb, var(--phosphor) 35%, transparent); }
.gs-pips { display: flex; align-items: flex-end; gap: 4px; margin-left: auto; padding-left: 0.5rem; }
.gs-pips i { display: block; width: 5px; height: 0.9rem; background: var(--phosphor); box-shadow: 0 0 6px color-mix(in srgb, var(--phosphor) 80%, transparent); opacity: 0.55; }
.gs-pips i:first-child { height: 1.15rem; opacity: 1; background: var(--phosphor-bright); }
.vera-glass .glass-status[data-state=thinking] .gs-lamp { animation-duration: 1.3s; }
.vera-glass .glass-status[data-state=thinking] .gs-lamp::after { animation-duration: 1.3s; }
.vera-glass .glass-status:is([data-state=retrying], [data-state=lost]) { color: var(--people); text-shadow: none; background: linear-gradient(90deg, color-mix(in srgb, var(--people) 14%, transparent), transparent 75%); border-top-color: color-mix(in srgb, var(--people) 45%, transparent); }
.vera-glass .glass-status:is([data-state=retrying], [data-state=lost]) .gs-lamp { background: var(--people); box-shadow: 0 0 6px color-mix(in srgb, var(--people) 60%, transparent); animation: none; }
.vera-glass .glass-status:is([data-state=retrying], [data-state=lost]) .gs-lamp::after { display: none; }
@keyframes gs-breathe { 0%, 100% { opacity: 1; } 50% { opacity: 0.62; } }
@keyframes gs-ring { 0% { opacity: 0.7; transform: scale(0.8); } 70%, 100% { opacity: 0; transform: scale(2.1); } }
@media (prefers-reduced-motion: reduce) { .gs-lamp, .gs-lamp::after { animation: none !important; } .gs-lamp::after { opacity: 0.35; transform: scale(1.5); } }
@media (max-width: 40rem) { .vera-glass .ask-question { font-size: 2.25rem; } .gs-pips i { width: 4px; } .vera-glass .glass-status { font-size: 1.2rem; } }

/* ---- GLASS: the tube beside the card, on its grid floor ---------------------------------------- */
.vera-tube { display: flex; flex-direction: column; min-width: 0; }
.vera-tube .crt-tube { flex: 1; display: flex; flex-direction: column; }
.vera-tube .crt-tube > .pic { flex: 1; align-content: start; }
.vera-tube .next-block { margin-top: 0; padding-top: 0; border-top: 0; align-content: start; }
.vera-tube .next-up .next-title, .vera-tube .next-title { font-size: 2.1rem; }
.vera-tube .when-plot { position: relative; z-index: 1; margin-top: 0.8rem; }
.tube-floor {
  position: absolute; z-index: 0; left: -30%; right: -30%; bottom: -2px; height: 58%; pointer-events: none;
  background:
    linear-gradient(to right, color-mix(in srgb, var(--phosphor) 38%, transparent) 1px, transparent 1px) 50% 0 / 34px 100%,
    linear-gradient(to bottom, color-mix(in srgb, var(--phosphor) 38%, transparent) 1px, transparent 1px) 0 0 / 100% 26px;
  transform: perspective(170px) rotateX(58deg); transform-origin: 50% 100%;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 60%); mask-image: linear-gradient(to bottom, transparent, #000 60%);
  filter: blur(0.3px) drop-shadow(0 0 2px color-mix(in srgb, var(--phosphor) 50%, transparent)); opacity: 0.75;
}
.vera-tube .crt-tube > .pic { z-index: 1; }
@media (prefers-contrast: more) { .tube-floor { opacity: 0.4; } }

/* ---- TYPE: reading prose sets at 1.55 leading and never runs wider than 66 characters ---------- */
main :is(p.muted, p.hint, .lede, p.lead, .why, .description, .said-text, p.step-skip-note, p.summary, p.memory-fact, p.state-line, .band-note, .section-state, .capture > p):not(.panel, .row, .error, .said, .warn) {
  line-height: 1.55; max-width: 66ch;
}
.said-text { max-width: 66ch; line-height: 1.55; }

/* ==== r19-mut-1: three rolled changes on Desk Terminal, Vera Card ==================================
   GLASS     the dock row: Coming up under the question and the Contents plate (with the status line)
             under the tube, on the same two columns as the Vera row, so Home's first screen is full
             and the desk's left column no longer ends under the plate. .dock-row .dock-coming .dock-terminal
   CONTROLS  phone: a big Send key with its word and a tall composer; Ideas: each bank of filter keys is one
             compact row (a row that slides sideways on a phone, a flowing row on a desk). .keys .key-row
   LIST      desktop: row text one size up, the amber "was due" kept, and a fine lit track threaded down
             the To do rows through their ticks. .tracked
   ================================================================================================== */

/* ---- GLASS: the dock row ------------------------------------------------------------------------ */
.page-home main > .terminal { display: none; }
.dock-row, .dock-coming { display: contents; }
.dock-terminal { align-self: start; }
@media (min-width: 64rem) {
  .dock-row { display: grid; grid-template-columns: minmax(0, 1.22fr) minmax(0, 1fr); gap: 1.5rem; align-items: start; min-width: 0; grid-column: 1 / -1; grid-row: 2; }
  .dock-coming { display: block; min-width: 0; }
  .dock-terminal { position: relative; }
  /* the desk is the third row now, two columns on the same measure: To do, and Finish setting up beside it */
  .page-home main > .desk { grid-column: 1 / -1; grid-row: 3; display: grid; grid-template-columns: minmax(0, 1.22fr) minmax(0, 1fr); gap: 1rem 1.5rem; align-items: start; }
  .page-home .desk > .said, .page-home .desk > .error, .page-home .desk > .home-wishes { grid-column: 1 / -1; }
  .page-home .desk > .home-todo { grid-column: 1; }
  .page-home .desk > .setup { grid-column: 2; }
  .page-home .desk:not(:has(> .setup)) > .home-todo { grid-column: 1 / -1; }
  .page-home main > .lower { grid-row: 4; }
  .home-todo .checklist > .row { grid-template-columns: 2.75rem minmax(0, max-content) minmax(0.75rem, 1fr) 3.5rem 11.5rem; }
  .home-todo .colheads .ch-who { width: 3.5rem; } .home-todo .colheads .ch-due { width: 11.5rem; }
  .page-home .setup .steps .t { white-space: normal; overflow: visible; line-height: 1.4; padding-block: 0.5rem; margin-block: 0; }
}

/* ---- CONTROLS: a big Send, a tall composer; one row of filter keys ------------------------------ */
@media (max-width: 40rem) {
  .ask textarea, .vera-deck .ask textarea { min-height: 7.25rem; padding: 0.8rem 0.9rem; font-size: 1.0625rem; line-height: 1.5; }
  .ask-bar { gap: 0.6rem; margin-top: 0.65rem; }
  .ask .who { flex: 1 1 100%; }
  .ask .who select { min-height: 3.25rem; font-size: 1rem; }
  .ask .mic-slot { margin-left: 0; }
  .ask button.mic { width: 3.5rem; height: 3.5rem; min-height: 3.5rem; }
  .ask .send {
    flex: 1 1 8rem; width: auto; min-width: 8rem; min-height: 3.5rem; padding: 0 1.5rem; gap: 0.55rem;
    font-size: 1.1875rem; font-weight: 700; letter-spacing: 0.01em;
  }
  .ask .send .label { position: static; width: auto; height: auto; overflow: visible; clip-path: none; }
  .ask .send .icon { width: 1.4rem; height: 1.4rem; }
  .ask .locate label { min-height: 3rem; font-size: 1rem; }
  /* the chat's box is pinned above the tabs: taller, still one row of keys */
  .page-chat .composer { max-height: 15.5rem; }
  .page-chat .composer .ask textarea { min-height: 4.5rem; height: 4.5rem; }
  .page-chat .composer .ask .who { flex: 1 1 0; }
  .page-chat .composer .ask-bar { gap: 0.5rem; margin-top: 0.5rem; }
  .page-chat .composer .ask .send { flex: none; min-width: 6.75rem; min-height: 3.25rem; padding: 0 1.1rem; }
  .page-chat .composer .ask button.mic { width: 3.25rem; height: 3.25rem; min-height: 3.25rem; }
  .page-chat .composer .ask .who select { min-height: 3.25rem; white-space: nowrap; text-overflow: ellipsis; font-size: 0.9375rem; }
  .page-chat .composer .ask .who label { font-size: 0.8125rem; }
  .page-chat .thread-band { margin-bottom: 12rem; }
}
/* Ideas: every bank of keys is one row. On a phone it slides sideways under a fade; on a desk it flows
   across the plate's width in compact keys instead of two columns of tall ones. */
.page-ideas .deck-body .keys { grid-template-columns: 3.1rem minmax(0, 1fr); column-gap: 0.25rem; }
.page-ideas .deck-body .key-row, .page-ideas .deck-body .kinds .key-row { display: flex; flex-wrap: wrap; gap: 0.3125rem; }
.page-ideas .deck-body .key { flex: none; padding: 0 0.6rem; gap: 0.35rem; }
.page-ideas .deck-body .key[aria-current] { padding-right: 1.2rem; }
@media (max-width: 63.99rem) {
  .page-ideas .deck-body .keys { grid-template-columns: minmax(0, 1fr); row-gap: 0.1rem; }
  .page-ideas .deck-body .keys-name { padding: 0.4rem 0 0.2rem; }
  .page-ideas .deck-body .key-row, .page-ideas .deck-body .kinds .key-row {
    flex-wrap: nowrap; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scrollbar-width: none;
    margin-inline: -0.25rem; padding: 4px 1.5rem 4px 0.25rem;
    -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 2rem), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 2rem), transparent);
  }
  .page-ideas .deck-body .key-row::-webkit-scrollbar { display: none; }
  .page-ideas .deck-body .key { scroll-snap-align: start; scroll-margin-inline: 0.25rem; }
}

/* ---- LIST: row text one size up, a fine lit track through the To do ticks ---------------------- */
@media (min-width: 64rem) {
  .rows .t, .timetable .t, .checklist .t { font-size: 1.1875rem; }
  .rows .sub { font-size: 1rem; }
  .rows :is(.f, .who, .for, .day, .time, .rel), .checklist .who, .timetable .who, .timetable .f, .dated .day, .idea-card .for { font-size: 1rem; }
  /* the wider type takes a little of the facts' room back: */
  .idea-list > .row { grid-template-columns: 1.5rem minmax(0, max-content) auto minmax(0.75rem, 1fr) 8rem 6.5rem 2.5rem; }
  .idea-band .colheads .ch-drive { width: 8rem; padding-right: 2.5rem; } .idea-band .colheads .ch-for { width: 6.5rem; }
  .dated .day .dnum { font-size: 1rem; }
  /* The track: a rail down the left of the list, lit, with a short branch to each tick; it runs from the first
     tick to the last (the rows' own height is 2.75rem, so a tick sits 1.375rem down). */
  .tracked > .row:not(.empty), .tracked > .row:not(.empty):not(.step):hover {
    --track: var(--lit); --tx: 0.3125rem; --ty: 1.375rem;
    background-image:
      linear-gradient(var(--track), var(--track)),
      linear-gradient(90deg, transparent, color-mix(in srgb, var(--track) 34%, transparent) 50%, transparent),
      linear-gradient(var(--track), var(--track));
    background-repeat: no-repeat;
    background-size: 3px 100%, 20px 100%, 0.8rem 2px;
    background-position: var(--tx) 0, calc(var(--tx) - 8.5px) 0, var(--tx) calc(var(--ty) - 1px);
  }
  .tracked > .row:not(.empty):first-child, .tracked > .row:not(.empty):first-child:not(.step):hover {
    background-size: 3px calc(100% - var(--ty)), 20px calc(100% - var(--ty)), 0.8rem 2px;
    background-position: var(--tx) var(--ty), calc(var(--tx) - 8.5px) var(--ty), var(--tx) calc(var(--ty) - 1px);
  }
  .tracked > .row:not(.empty):last-child, .tracked > .row:not(.empty):last-child:not(.step):hover {
    background-size: 3px calc(var(--ty) + 1px), 20px calc(var(--ty) + 1px), 0.8rem 2px;
  }
  .tracked > .row:not(.empty):only-child, .tracked > .row:not(.empty):only-child:not(.step):hover { background-image: none; }
}
@media (prefers-contrast: more) {
  .tracked > .row:not(.empty) { --track: var(--brand); }
}
/* ==== r20-mut-1: three rolled changes on Desk Terminal, Docked Track ==============================
   GLASS  the dock row ends together (Coming up and the Contents plate stretch to one height, each with its foot
          pinned), and the tube column on Settings, Status and Plans is 21rem instead of 26rem, so their lists
          get the width. .dock-row .dock-coming .dock-terminal; body.page-status/-plans/-settings main
   RULE   thinner chrome: a band is an open section under its rule (no plate) unless it holds the dock, a
          warning or a capture form; Finish setting up is Home's first band, a strip of its steps side by side.
          .band--open .setup-first
   HEAD   Home's question one step bolder: 56px (up from 44px), heavier strokes and a hotter core so it wins
          when squinted. .vera-glass .ask-question
   ================================================================================================== */

/* ---- HEAD ---------------------------------------------------------------------------------------- */
.vera-glass .ask-question {
  color: color-mix(in srgb, var(--phosphor) 92%, #fff);
  -webkit-text-stroke: 1.1px currentColor; paint-order: stroke fill;
  text-shadow:
    0 0 1px color-mix(in srgb, var(--phosphor) 90%, transparent),
    0 0 0.16em color-mix(in srgb, var(--phosphor) 60%, transparent),
    0 0 0.5em color-mix(in srgb, var(--phosphor) 34%, transparent);
}
@media (min-width: 64rem) {
  .vera-glass .ask-question { font-size: 3.5rem; line-height: 0.95; margin-top: 0.15rem; }
}
@media (min-width: 40.01rem) and (max-width: 63.99rem) {
  .vera-glass .ask-question { font-size: 3rem; }
}
@media (max-width: 40rem) {
  .vera-glass .ask-question { font-size: 2.5rem; -webkit-text-stroke-width: 0.8px; }
}

/* ---- GLASS: the dock ends together; a narrower tube column ------------------------------------- */
@media (min-width: 64rem) {
  .dock-row { align-items: stretch; }
  .dock-coming { display: flex; flex-direction: column; }
  .dock-coming > .band.coming { flex: 1 1 auto; display: flex; flex-direction: column; border-bottom: 1px solid color-mix(in srgb, var(--c) 40%, var(--rule)); }
  .dock-coming > .band.coming > .rail { flex: 1 1 auto; display: flex; flex-direction: column; }
  .dock-coming .rail > .dated { flex: 1 1 auto; display: grid; grid-auto-rows: minmax(2.75rem, 1fr); }
  .dock-coming .rail > .dated > .row { align-items: center; }
  .dock-coming > .band.coming > .band-note { margin-top: auto; padding-top: 0.6rem; }
  .dock-terminal { align-self: stretch; }
  .dock-terminal > .contents { flex: 1 1 auto; }
  .dock-terminal > .status-foot { margin-top: auto; }

  .page-status main, .page-plans main, .page-settings main { grid-template-columns: 21rem minmax(0, 1fr); column-gap: 1.5rem; }
  .page-status .contents-list .c-t, .page-plans .contents-list .c-t { flex: none; white-space: nowrap; }
  .page-status .contents-list .c-sig { gap: 3px; }
  .page-status .contents-list .lead { flex-basis: 0.5rem; min-width: 0.5rem; }
}

/* ---- RULE: an open band, and the setup strip first --------------------------------------------- */
.band:not(.coming, .setup, .trouble, .attention, .capture, .restaurants-link) { background: transparent; }
.band:not(.coming, .setup, .trouble, .attention, .capture, .restaurants-link) .band-head .ring:not(.look) { background: var(--bg); }
@media (min-width: 64rem) {
  .band:not(.coming, .setup, .trouble, .attention, .capture, .restaurants-link) { padding-inline: 0.75rem; }
  .page-home main > .vera-row { grid-row: auto; }
  .page-home main > .setup-first, .page-home main > .dock-row, .page-home main > .desk, .page-home main > .lower { grid-column: 1 / -1; grid-row: auto; }
}
.setup-first { padding-top: 0.5rem; padding-bottom: 0.7rem; }
.setup-first .band-head { min-height: 2.5rem; margin-bottom: 0.15rem; }
.setup-first .band-note { margin: 0.2rem 0 0; }
@media (min-width: 64rem) {
  .setup-first { padding-inline: 1.25rem; }
  .setup-first .steps { padding-left: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: 1.75rem; row-gap: 0; }
  .band.setup-first .steps > .row.step { align-items: start; border-bottom: 0; background: none; box-shadow: none; }
  .page-home .setup-first .steps .t { padding-block: 0.4rem; font-size: 1.0625rem; }
}
